CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,owner_id TEXT,subject_type TEXT NOT NULL,intended_use TEXT NOT NULL,quality TEXT NOT NULL DEFAULT 'standard',status TEXT NOT NULL,current_job_id TEXT,base_version_id TEXT,passed_stages INTEGER NOT NULL DEFAULT 0,total_stages INTEGER NOT NULL DEFAULT 9,actual_backend TEXT,thumbnail_url TEXT,settings TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL,original_name TEXT NOT NULL,storage_path TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,width INTEGER,height INTEGER,sha256 TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_assets_project ON assets(project_id,role,active);
CREATE TABLE IF NOT EXISTS validations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),asset_snapshot TEXT NOT NULL,verdict TEXT NOT NULL,checks TEXT NOT NULL,risks TEXT NOT NULL,accepted_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),number INTEGER NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL,quality_report TEXT,created_at TEXT NOT NULL,UNIQUE(project_id,number));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),version_id TEXT NOT NULL REFERENCES versions(id),status TEXT NOT NULL,config_snapshot TEXT NOT NULL,requested_backend TEXT NOT NULL,actual_backend TEXT,model_version TEXT,seed INTEGER,current_stage TEXT,attempt INTEGER NOT NULL,created_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,error_code TEXT,error_summary TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stages(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),stage_key TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL,position INTEGER NOT NULL,started_at TEXT,completed_at TEXT,report_path TEXT,UNIQUE(job_id,stage_key));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT NOT NULL REFERENCES jobs(id),event_type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),version_id TEXT NOT NULL REFERENCES versions(id),type TEXT NOT NULL,label TEXT NOT NULL,storage_path TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,sha256 TEXT NOT NULL,metadata TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),decision TEXT NOT NULL,notes TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),payload TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS refinement_jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_version_id TEXT NOT NULL REFERENCES versions(id),output_version_id TEXT REFERENCES versions(id),status TEXT NOT NULL,config TEXT NOT NULL,module_states TEXT NOT NULL,logs TEXT NOT NULL,created_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,error_summary TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0,blender_version TEXT,quality_report TEXT);
CREATE TABLE IF NOT EXISTS version_links(id TEXT PRIMARY KEY,parent_version_id TEXT NOT NULL REFERENCES versions(id),child_version_id TEXT NOT NULL REFERENCES versions(id),refinement_job_id TEXT NOT NULL REFERENCES refinement_jobs(id),created_at TEXT NOT NULL,UNIQUE(child_version_id));
CREATE TABLE IF NOT EXISTS refinement_artifacts(id TEXT PRIMARY KEY,refinement_job_id TEXT NOT NULL REFERENCES refinement_jobs(id),version_id TEXT NOT NULL REFERENCES versions(id),type TEXT NOT NULL,label TEXT NOT NULL,storage_path TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,sha256 TEXT NOT NULL,metadata TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS version_comments(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),version_id TEXT NOT NULL REFERENCES versions(id),number INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL,recommended_route TEXT NOT NULL,mesh_name TEXT,position_json TEXT,normal_json TEXT,camera_snapshot_json TEXT,screenshot_path TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT,UNIQUE(project_id,number));
CREATE INDEX IF NOT EXISTS idx_version_comments_version ON version_comments(version_id,status);
CREATE TABLE IF NOT EXISTS comment_replies(id TEXT PRIMARY KEY,comment_id TEXT NOT NULL REFERENCES version_comments(id),author_type TEXT NOT NULL,body TEXT NOT NULL,attachments_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comment_attachments(id TEXT PRIMARY KEY,comment_id TEXT NOT NULL REFERENCES version_comments(id),asset_id TEXT NOT NULL REFERENCES assets(id),view_role TEXT NOT NULL,purpose TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reference_sets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),number INTEGER NOT NULL,parent_reference_set_id TEXT REFERENCES reference_sets(id),status TEXT NOT NULL,consistency_report TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,locked_at TEXT,UNIQUE(project_id,number));
CREATE TABLE IF NOT EXISTS reference_set_assets(id TEXT PRIMARY KEY,reference_set_id TEXT NOT NULL REFERENCES reference_sets(id),asset_id TEXT NOT NULL REFERENCES assets(id),view_role TEXT NOT NULL,purpose TEXT NOT NULL,source_comment_id TEXT REFERENCES version_comments(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revision_requests(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_version_id TEXT NOT NULL REFERENCES versions(id),output_version_id TEXT REFERENCES versions(id),reference_set_id TEXT REFERENCES reference_sets(id),status TEXT NOT NULL,route TEXT NOT NULL,config_snapshot TEXT NOT NULL,logs TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,error_summary TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS revision_comment_links(id TEXT PRIMARY KEY,revision_request_id TEXT NOT NULL REFERENCES revision_requests(id),comment_id TEXT NOT NULL REFERENCES version_comments(id),source_version_id TEXT NOT NULL REFERENCES versions(id),output_version_id TEXT REFERENCES versions(id),result_status TEXT,result_notes TEXT,created_at TEXT NOT NULL,reviewed_at TEXT,UNIQUE(revision_request_id,comment_id));
CREATE TABLE IF NOT EXISTS detail_plans(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_reference_set_id TEXT NOT NULL REFERENCES reference_sets(id),status TEXT NOT NULL,mode TEXT NOT NULL,analyzer_version TEXT NOT NULL,summary_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,confirmed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_detail_plans_project ON detail_plans(project_id,created_at);
CREATE TABLE IF NOT EXISTS detail_regions(id TEXT PRIMARY KEY,detail_plan_id TEXT NOT NULL REFERENCES detail_plans(id),region_key TEXT NOT NULL,mask_asset_id TEXT REFERENCES assets(id),visible_views_json TEXT NOT NULL DEFAULT '[]',coverage_score REAL NOT NULL,clarity_score REAL NOT NULL,consistency_score REAL NOT NULL,evidence_level TEXT NOT NULL,target_usage TEXT NOT NULL,risk_level TEXT NOT NULL,recommended_views_json TEXT NOT NULL DEFAULT '[]',constraints_json TEXT NOT NULL DEFAULT '{}',selected INTEGER NOT NULL DEFAULT 0,UNIQUE(detail_plan_id,region_key));
CREATE TABLE IF NOT EXISTS detail_generation_jobs(id TEXT PRIMARY KEY,detail_plan_id TEXT NOT NULL REFERENCES detail_plans(id),status TEXT NOT NULL,provider TEXT NOT NULL,model TEXT,workflow_version TEXT,seed INTEGER NOT NULL,parameters_json TEXT NOT NULL DEFAULT '{}',started_at TEXT,finished_at TEXT,error_code TEXT,error_message TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,current_step INTEGER NOT NULL DEFAULT 0,total_steps INTEGER NOT NULL DEFAULT 0,current_message TEXT,logs_json TEXT NOT NULL DEFAULT '[]');
CREATE INDEX IF NOT EXISTS idx_detail_jobs_plan ON detail_generation_jobs(detail_plan_id,created_at);
CREATE TABLE IF NOT EXISTS detail_candidate_groups(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES detail_generation_jobs(id),region_id TEXT NOT NULL REFERENCES detail_regions(id),group_index INTEGER NOT NULL,status TEXT NOT NULL,evidence_level TEXT NOT NULL,target_usage TEXT NOT NULL,consistency_metrics_json TEXT NOT NULL DEFAULT '{}',reviewed_at TEXT,review_note TEXT,UNIQUE(job_id,region_id,group_index));
CREATE TABLE IF NOT EXISTS detail_candidate_assets(id TEXT PRIMARY KEY,candidate_group_id TEXT NOT NULL REFERENCES detail_candidate_groups(id),asset_id TEXT NOT NULL REFERENCES assets(id),view_role TEXT NOT NULL,camera_json TEXT NOT NULL DEFAULT '{}',source_asset_id TEXT REFERENCES assets(id),mask_asset_id TEXT REFERENCES assets(id),created_at TEXT NOT NULL,UNIQUE(candidate_group_id,view_role));
CREATE TABLE IF NOT EXISTS detail_review_events(id TEXT PRIMARY KEY,candidate_group_id TEXT NOT NULL REFERENCES detail_candidate_groups(id),action TEXT NOT NULL,actor TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',reference_set_id TEXT REFERENCES reference_sets(id),created_at TEXT NOT NULL);
